        function normalizeName(value) {
            return String(value || '').normalize('NFKC').toLowerCase().replace(/[\s　]/g, '').replace(/[‐‑‒–—−]/g, '-');
        }
        function normalizeAndDedupeData() {
            (db.members || []).forEach(m => { for (const k of ["status","currentStatus","nextMonthStatus"]) if(m[k] === "提案中") m[k] = "待機中"; });
            const clientByName = new Map();
            const clientIdMap = {};
            const uniqueClients = [];
            (db.clients || []).forEach(c => {
                const key = normalizeName(c.name);
                if (key && clientByName.has(key)) {
                    const keep = clientByName.get(key);
                    clientIdMap[c.id] = keep.id;
                    Object.keys(c).forEach(k => { if ((keep[k] === '' || keep[k] == null) && c[k] !== '' && c[k] != null) keep[k] = c[k]; });
                } else { clientByName.set(key, c); uniqueClients.push(c); clientIdMap[c.id] = c.id; }
            });
            db.clients = uniqueClients;
            const projectByKey = new Map();
            const uniqueProjects = [];
            (db.projects || []).forEach(p => {
                if (clientIdMap[p.clientId]) p.clientId = clientIdMap[p.clientId];
                const client = db.clients.find(c => c.id === p.clientId);
                if (client) p.clientName = client.name;
                const key = normalizeName(p.clientName || p.clientId) + '|' + normalizeName(p.title);
                if (key !== '|' && projectByKey.has(key)) {
                    const keep = projectByKey.get(key);
                    keep.assignedMemberIds = [...new Set([...(keep.assignedMemberIds || []), ...(p.assignedMemberIds || [])])];
                    keep.participants = [...(keep.participants || []), ...(p.participants || [])];
                    if (p.status === '参画中') keep.status = '参画中';
                    Object.keys(p).forEach(k => { if ((keep[k] === '' || keep[k] == null) && p[k] !== '' && p[k] != null) keep[k] = p[k]; });
                } else { projectByKey.set(key, p); uniqueProjects.push(p); }
            });
            db.projects = uniqueProjects;
            db.projects.forEach(p => {
                p.assignedMemberIds = Array.isArray(p.assignedMemberIds) ? [...new Set(p.assignedMemberIds)] : [];
                p.participants = Array.isArray(p.participants) ? p.participants : [];
                // Legacy project prices are stored in 10,000-yen units; preserve them and add a yen-precision field.
                if (!Number.isFinite(Number(p.priceYen))) p.priceYen = Math.round((Number(p.price) || 0) * 10000);
                p.participants = p.participants.filter((x, i, arr) => x && x.memberId && arr.findIndex(y => y.memberId === x.memberId) === i).map(x => ({ ...x, rateYen: Math.max(0, Math.round(Number(x.rateYen) || 0)) }));
            });
        }
        function projectPriceYen(p) { return Math.max(0, Math.round(Number(p.priceYen != null ? p.priceYen : (Number(p.price) || 0) * 10000) || 0)); }
        function formatYenAsMan(yen) { return (Number(yen || 0) / 10000).toLocaleString('ja-JP', { minimumFractionDigits: 0, maximumFractionDigits: 4 }); }
        let projectDetailId = null;


        function seedMemberTransportDefaults() {
            const seed = [["MEM-101", "川合 要", 18310], ["MEM-102", "山田 裕也", 9870], ["MEM-114", "佐々木 翔平", 11510], ["MEM-109", "生天目 慧海", 12650], ["MEM-108", "梶原 悠羽", 9870], ["MEM-115", "古山 淳詞", 17800], ["MEM-110", "内海 未奈子", 13120], ["MEM-104", "佐々木 七海", 9870], ["MEM-116", "稲毛 遼河", 15710], ["MEM-111", "高橋 響哉", 9870], ["MEM-112", "澤村 吏久", 9870], ["MEM-117", "鹿又 翔二朗", 16610], ["MEM-105", "小関 彩乃", 16060], ["MEM-113", "正木 裕多竜", 7840], ["MEM-118", "遠藤 新太", 17750], ["MEM-103", "伊藤 快成", 11510], ["MEM-119", "鈴木 裕斗", 17400], ["MEM-106", "曽根 美咲", 14780], ["MEM-120", "滝沢 陽", 17400], ["MEM-107", "久保 奈美礼", 9870]];
            db.memberTransportDefaultsApplied = db.memberTransportDefaultsApplied || {};
            for (const [id,name,yen] of seed) {
                if (db.memberTransportDefaultsApplied[id]) continue;
                const member = db.members.find(m => m.id === id && String(m.name).replace(/\s/g,'') === name.replace(/\s/g,''));
                if (!member) continue;
                member.transportCost = yen / 10000;
                for (const key of Object.keys(db.monthlyTransport || {})) {
                    if (key.startsWith(id+'|')) delete db.monthlyTransport[key];
                }
                db.memberTransportDefaultsApplied[id] = true;
            }
        }

        function seedMemberRates15() {
            seedMemberTransportDefaults();
            if (!db.memberGradeNabatameCorrected) {
                const member = db.members.find(m => m.id === "MEM-109" && m.name.replace(/\s/g, "") === "生天目慧海");
                if (member) {
                    member.grade = "G3";
                    db.memberGradeNabatameCorrected = true;
                }
            }
            if (db.memberRates15Seeded && db.memberGrades15Linked) return;
            const seedRates = !db.memberRates15Seeded;
            const linkGrades = !db.memberGrades15Linked;
            if (!Array.isArray(db.memberRates)) db.memberRates = [];
            const seed = [[102, "山田 裕也", "M2", 510000, 650000, 4], [103, "伊藤 快成", "G3", 450000, 480000, 8], [104, "佐々木 七海", "G2", 440000, 500000, 1], [105, "小関 彩乃", "G2", 350000, 400000, 4], [106, "曽根 美咲", "G1", 400000, 440000, 4], [107, "久保 奈美礼", "G2", 100000, 400000, 1], [108, "梶原 悠羽", "G3", 500000, 530000, 4], [109, "生天目 慧海", "G3", 650000, 650000, null], [110, "内海 未奈子", "G3", 480000, 520000, 4], [111, "高橋 響哉", "G2", 370000, 400000, 7], [112, "澤村 吏久", "G2", 400000, 450000, 4], [113, "正木 裕多竜", "G2", 350000, 370000, 7], [115, "古山 淳詞", "G3", 430000, 430000, null], [114, "佐々木 翔平", "G4", 420000, 420000, null], [116, "稲毛 遼河", "G2", 350000, 400000, 4], [117, "鹿又 翔二朗", "G2", 400000, 410000, 4], [118, "遠藤 新太", "G2", 350000, 380000, 4], [119, "鈴木 裕斗", "G2", 380000, 400000, 4], [120, "滝沢 陽", "G1", 360000, 400000, 4]];
            if (linkGrades) {
                const kawai = db.members.find(m => m.id === "MEM-101" && m.name.replace(/\s/g, "") === "川合要");
                if (kawai) kawai.grade = "G3";
            }
            for (const [id,name,grade,previous,rate,startMonth] of seed) {
                const member = db.members.find(m => m.id === 'MEM-'+id && m.name.replace(/\s/g,'') === name.replace(/\s/g,''));
                if (!member) continue;
                if (linkGrades) member.grade = grade;
                if (seedRates && !db.memberRates.some(r => r.memberId === member.id && r.year === 2026)) {
                    db.memberRates.push({memberId:member.id,year:2026,previous,rate,startMonth,status:'未交渉'});
                }
            }
            db.memberRates15Seeded = true;
            db.memberGrades15Linked = true;
        }

        function alignClientIds(data) {
            const map = new Map();
            let seq = Math.max(Number(data.clientIdSequence)||0, ...data.clients.map(c=>/^CLI-\d+$/.test(c.id)?Number(c.id.slice(4)):0));
            for(const c of data.clients) if(!/^CLI-\d+$/.test(c.id)) map.set(c.id, `CLI-${String(++seq).padStart(3,'0')}`);
            function walk(o){if(!o||typeof o!=='object')return;for(const k of Object.keys(o)){if(typeof o[k]==='string'&&map.has(o[k]))o[k]=map.get(o[k]);else if(typeof o[k]==='object')walk(o[k]);}}
            walk(data); data.clientIdSequence=seq;
        }
        alignClientIds(DEFAULT_INITIAL_DATA);
        alignClientIds(db);

        function loadStoredData() {
            const INITIAL_DATA_SEED_VERSION = 'sescore-seed-2026-11-25-v3.2.131';
            const appliedSeedVersion = localStorage.getItem('ses_access_seed_version');
            const stored = localStorage.getItem('ses_access_db');
            // Apply the supplied 2026-11-25 backup as the initial data exactly once for this release.
            // After this one-time setup, subsequent user edits are preserved normally.
            if (appliedSeedVersion !== INITIAL_DATA_SEED_VERSION) {
                db = JSON.parse(JSON.stringify(DEFAULT_INITIAL_DATA));
                try {
                    localStorage.setItem('ses_access_db', JSON.stringify(db));
                    localStorage.setItem('ses_access_seed_version', INITIAL_DATA_SEED_VERSION);
                } catch (e) {}
            } else if (stored) {
                try {
                    db = JSON.parse(stored);
                } catch (e) {
                    db = JSON.parse(JSON.stringify(DEFAULT_INITIAL_DATA));
                }
            } else {
                db = JSON.parse(JSON.stringify(DEFAULT_INITIAL_DATA));
                try { localStorage.setItem('ses_access_db', JSON.stringify(db)); } catch (e) {}
            }
            // Annual goals for FY2027 / 15th term; preserve any existing user-entered values.
            if (!db.fiscalTargets || typeof db.fiscalTargets !== 'object') db.fiscalTargets = {};
            if (!db.fiscalTargets['2026']) db.fiscalTargets['2026'] = db.fiscalTargets['2027'] || { revenue: 10800, profit: 1184 };
            // Ensure expected collections exist, without overwriting user-provided member statuses or rates.
            db.metadata = db.metadata || { systemName: 'SES_Core', version: '3.0.0', schemaVersion: '3.0.0' };
            ['clients','projects','members','interviews','tasks','auditLog','spotJobs','expenses','oneOnOnes','feedbacks'].forEach(key => {
                if (!Array.isArray(db[key])) db[key] = [];
            });
            ['monthlyRevenue','monthlyCost','monthlyTransport','monthlyRevenueActual','monthlyCostActual','monthlyTransportActual'].forEach(key => {
                if (!db[key] || typeof db[key] !== 'object' || Array.isArray(db[key])) db[key] = {};
            });
            normalizeAndDedupeData();
            alignClientIds(db);
            window.sortMembersByPreferredOrder(db.members);
            seedMemberRates15();
            try { localStorage.setItem('ses_access_db', JSON.stringify(db)); } catch (e) {}
        }

        function confirmResetData() {
            if(window.sesRestricted?.()) return;
            if (confirm("すべてのデータを初期のサンプルデータにリセットしますか？この操作は取り消せません。")) {
                db = JSON.parse(JSON.stringify(DEFAULT_INITIAL_DATA));
                seedMemberRates15();
                window.syncGradeCosts?.();
                saveStoredData();
            }
        }

        // ----------------------------------------------------
        // 5. JSON IMPORT / EXPORT
        // ----------------------------------------------------
        function exportDataJSON() {
            if(window.sesRestricted?.()) return;
            db.metadata.exportedAt = new Date().toISOString();
            const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(db, null, 2));
            const downloadAnchor = document.createElement('a');
            downloadAnchor.setAttribute("href", dataStr);
            downloadAnchor.setAttribute("download", `SES_Core_Backup_${new Date().toISOString().slice(0,10)}.json`);
            document.body.appendChild(downloadAnchor);
            downloadAnchor.click();
            downloadAnchor.remove();
        }

        function openImportModal() {
            if(window.sesRestricted?.()) return;
            selectedImportFileContent = null;
            document.getElementById('import-file-name').innerText = '';
            document.getElementById('modal-import').classList.remove('hidden');
        }

        function handleFileSelect(event) {
            const file = event.target.files[0];
            if (!file) return;

            document.getElementById('import-file-name').innerText = file.name;
            const reader = new FileReader();
            reader.onload = function(e) {
                selectedImportFileContent = e.target.result;
            };
            reader.readAsText(file);
        }

        function processJSONImport() {
            if(window.sesRestricted?.()) return;
            if (!selectedImportFileContent) {
                alert("インポートするJSONファイルを選択してください。");
                return;
            }

            try {
                const parsed = JSON.parse(selectedImportFileContent);
                if (!parsed.clients || !parsed.projects || !parsed.members) {
                    throw new Error("フォーマットが不正です。必要なフィールドが含まれていません。");
                }
                db = parsed;
                normalizeAndDedupeData();
            alignClientIds(db);
                saveStoredData();
                closeModal('modal-import');
                alert("JSONデータの正常インポートが完了しました。");
            } catch (err) {
                alert("JSONファイルの解析エラー: " + err.message);
            }
        }

        // ----------------------------------------------------
        // 6. RENDER DATA & UI COMPONENTS
        // ----------------------------------------------------
        function renderAllViews() {
            renderDashboard();
            renderClientsTable();
            renderProjectsTable();
            renderMembersTable();
            renderInterviewsTable();
            renderRevenueView();
            updateModalDropdowns();
        }

        // --- DASHBOARD RENDER ---
        function renderDashboard() {
            const activeEng = db.members.filter(m => m.status === '稼働中').length;
            const benchEng = db.members.filter(m => m.status === '待机中' || m.status === '待機中').length;
            const totalEng = db.members.length;
            const activePrj = db.projects.filter(p => !['見送り','募集終了'].includes(p.status)).length;
            const totalCli = db.clients.filter(c => c.status === 'アクティブ').length;

            let totalRev = 0;
            let totalCost = 0;

            db.members.filter(m => m.status === '稼働中').forEach(m => {
                totalRev += (m.rate || 0);
                totalCost += (m.cost || 0);
            });

            const profit = totalRev - totalCost;
            const profitMargin = totalRev > 0 ? ((profit / totalRev) * 100).toFixed(1) : 0;
            const utilizationRate = totalEng > 0 ? ((activeEng / totalEng) * 100).toFixed(0) : 0;


        }

        // --- CLIENTS TABLE ---
        function clientDisplayText(value) {
            return String(value == null ? '' : value).replace(/[&<>"']/g, ch => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
        }
        function renderClientsTable() {
            const query = (document.getElementById('client-search')?.value || '').toLowerCase();
            const tbody = document.getElementById('clients-table-body');
            if (!tbody) return;
            const filtered = db.clients.filter(c => [c.name,c.contact,c.id,c.email].some(v => String(v || '').toLowerCase().includes(query)));
            tbody.innerHTML = filtered.map(c => {
                const index = db.clients.indexOf(c);
                return `<tr class="ses-client-row transition">
                    <td class="p-4 font-mono text-cyan-400">${clientDisplayText(c.id)}</td>
                    <td class="p-4"><div class="ses-client-company">${clientDisplayText(c.name)}</div></td>
                    <td class="p-4"><span class="ses-client-status ${c.status === 'アクティブ' ? 'is-active' : ''}"><span class="ses-client-dot"></span>${clientDisplayText(c.status || '未設定')}</span></td>
                    <td class="p-4 text-right"><button type="button" onclick="openClientDetailByIndex(${index})" class="ses-client-detail-button" title="取引先の詳細を開く" aria-label="${clientDisplayText(c.name)}の詳細を開く"><i class="fa-solid fa-arrow-up-right-from-square" aria-hidden="true"></i></button></td>
                </tr>`;
            }).join('') || '<tr><td colspan="4" class="p-6 text-center text-slate-400">該当する取引先がありません。</td></tr>';
        }
        function openClientDetailByIndex(index) {
            const c = db.clients[index];
            if (!c) return;
            const modal = document.getElementById('modal-client-detail');
            if (!modal) return;
            document.getElementById('client-detail-title').textContent = c.name || '取引先詳細';
            const field = (label,value) => `<div class="client-read-field"><label>${clientDisplayText(label)}</label><div class="client-read-value">${clientDisplayText(value == null || value === '' ? '未登録' : String(value))}</div></div>`;
            const heading = title => `<div class="ses-client-section-title">${title}</div>`;
            const extras = [];
            const walk = (value,path,label) => {
                if(window.sesRestricted() && (path.some(window.sesMoneyField)||window.sesMoneyField(label)||Array.isArray(value)))return;
                if(value && typeof value === 'object' && !Array.isArray(value)) {
                    Object.entries(value).forEach(([key,child]) => walk(child,[...path,key],clientFieldLabels[key] || memberJapaneseLabel(key)));
                    return;
                }
                const display = Array.isArray(value) ? value.map(v => v && typeof v === 'object' ? Object.values(v).join('・') : v).join('、') : value;
                extras.push(field(label,display));
            };
            Object.entries(c).filter(([key]) => !clientStandardFields.has(key)).forEach(([key,value]) => walk(value,[key],clientFieldLabels[key] || memberJapaneseLabel(key)));
            document.getElementById('client-detail-fields').innerHTML = heading('基本情報') + field('企業名',c.name) + '<div class="client-read-spacer"></div>' + '<div class="client-read-wide">'+field('取引先区分',c.type)+'</div>' + heading('担当者情報') + field('担当者名',c.contact) + field('連絡先メールアドレス',c.email) + field('ステータス',c.status) + heading('取引先・打合せ情報') + extras.join('') + heading('管理情報') + field('取引先ID',c.id);
            document.getElementById('client-detail-edit').onclick = () => { closeModal('modal-client-detail'); editClient(c.id); };
            document.getElementById('client-detail-delete').onclick = () => { closeModal('modal-client-detail'); deleteClient(c.id); };
            modal.classList.remove('hidden');
        }

        // --- PROJECTS TABLE ---
        let projectViewMode = '共有案件';
        window.setProjectViewMode = function(mode) {
            projectViewMode = mode === '参画案件' ? '参画案件' : '共有案件';
            const shared = document.getElementById('project-mode-shared');
            const assigned = document.getElementById('project-mode-assigned');
            if (shared) { shared.className = projectViewMode === '共有案件' ? 'px-3 py-2 text-xs bg-cyan-600 text-white' : 'px-3 py-2 text-xs bg-slate-800 text-slate-300'; }
            if (assigned) { assigned.className = projectViewMode === '参画案件' ? 'px-3 py-2 text-xs bg-cyan-600 text-white' : 'px-3 py-2 text-xs bg-slate-800 text-slate-300'; }
            renderProjectsTable();
        };
        function inferredProjectType(p) {
            if (p.projectType === '参画案件' || p.projectType === '共有案件') return p.projectType;
            const linked = (db.members || []).some(m => m.assignedProjectId === p.id || m.currentProject === p.title) || (p.assignedMemberIds || []).length > 0;
            return linked ? '参画案件' : '共有案件';
        }
        function renderProjectsTable() {
            const query = document.getElementById('project-search').value.toLowerCase();
            const statusFilter = document.getElementById('project-filter-status').value;
            const tbody = document.getElementById('projects-table-body');

            const filtered = db.projects.filter(p => {
                const title = String(p.title || '');
                const skills = Array.isArray(p.skills) ? p.skills : [];
                const matchQuery = title.toLowerCase().includes(query) || skills.some(s => String(s).toLowerCase().includes(query));
                const matchStatus = statusFilter === 'ALL' || p.status === statusFilter;
                const matchMode = inferredProjectType(p) === projectViewMode;
                return matchQuery && matchStatus && matchMode;
            });

            tbody.innerHTML = filtered.map(p => `
                <tr class="hover:bg-slate-800/40 transition">
                    <td class="font-mono text-cyan-400">${projectInfoEscape(p.id)}</td>
                    <td class="font-bold text-slate-200">${projectInfoEscape(p.title)}</td>
                    <td class="text-slate-300">${projectInfoEscape(p.clientName || '取引先未登録')}</td>
                    <td><span class="px-3 py-1.5 rounded-lg text-xs border border-cyan-500/30 text-cyan-400">${projectInfoEscape(p.status || '未設定')}</span></td>
                    <td><button type="button" onclick="openProjectInfoByIndex(${db.projects.indexOf(p)})" class="ses-client-detail-button" title="案件の詳細を開く" aria-label="案件の詳細を開く"><i class="fa-solid fa-arrow-up-right-from-square" aria-hidden="true"></i></button></td>
                </tr>
            `).join('');
        }

        // --- MEMBERS TABLE ---
        function renderMembersTable() {
            const query = document.getElementById('member-search').value.toLowerCase();
            const statusFilter = document.getElementById('member-filter-status').value;
            const tbody = document.getElementById('members-table-body');

            const orderedMembers = window.sortMembersByPreferredOrder([...db.members]);
            const filtered = orderedMembers.filter(m => {
                const matchQuery = m.name.toLowerCase().includes(query) || m.skills.some(s => s.toLowerCase().includes(query));
                const matchStatus = statusFilter === 'ALL' || m.status === statusFilter;
                return matchQuery && matchStatus;
            });

            tbody.innerHTML = filtered.map((m, index) => `
                <tr class="ses-member-row hover:bg-slate-800/40 transition">
                    <td class="p-2 font-mono text-cyan-400"><div class="ses-member-id-cell"><span class="ses-member-actual-id" title="登録済み内部ID：${memberDetailEscape(m.id || '未設定')}">${window.getMemberDisplayId(m, orderedMembers)}</span></div></td>
                    <td class="p-2 font-bold text-slate-200">${memberDetailEscape(m.name)} <span class="ml-1 text-[9px] px-1.5 py-0.5 rounded bg-slate-700 text-slate-300 font-normal">${memberDetailEscape(m.type)}</span></td>
                    <td class="p-2 text-slate-300">${memberDetailEscape(m.department || '未登録')}</td>
                    <td class="p-2 text-slate-300">${memberDetailEscape(m.role || '未登録')}</td>
                    <td class="p-2 whitespace-nowrap">${memberDetailEscape(window.calculateTenure ? window.calculateTenure(m.hireDate) : (m.exp || '未登録'))}</td>
                    <td class="p-2"><div class="ses-member-status-compact"><span class="ses-member-status-label">現在</span><span class="ses-member-status-value" data-member-status="${memberDetailEscape(m.status || '未設定')}">${memberDetailEscape(m.status || '未設定')}</span><span class="ses-member-status-label">来月以降</span><span class="ses-member-status-value" data-member-status="${memberDetailEscape(m.nextMonthStatus || m.status || '未設定')}">${memberDetailEscape(m.nextMonthStatus || m.status || '未設定')}</span></div></td>
                    <td class="p-2 text-right"><button type="button" onclick="openMemberDetailByIndex(${db.members.indexOf(m)})" class="ses-client-detail-button ses-member-detail-action" title="社員の詳細を開く" aria-label="社員の詳細を開く"><i class="fa-solid fa-arrow-up-right-from-square" aria-hidden="true"></i></button></td>
                </tr>
            `).join('');
        }

        const memberFieldNames = {currentProject:'現在の参画案件',currentStatus:'現在のステータス',assignedProjectId:'参画案件ID',contractEnd:'契約終了日',transportCost:'基本交通費',manages:'管理対象メンバー',grade:'グレード',id:'社員ID',name:'氏名',type:'区分',department:'所属部署',role:'役職',skills:'保有スキル',hireDate:'入社日',exp:'在籍年数',rate:'受注単価（万円）',cost:'原価単価（万円）',available:'稼働可能日',status:'現在の状態',nextMonthStatus:'来月以降の状態',waitingStartDate:'待機開始日',email:'メールアドレス',phone:'電話番号',notes:'備考',createdAt:'登録日時',updatedAt:'更新日時',address:'住所',birthday:'生年月日',birthDate:'生年月日',gender:'性別',age:'年齢',company:'所属会社',companyName:'所属会社名',nearestStation:'最寄り駅',station:'最寄り駅',nationality:'国籍',experience:'経験年数',qualifications:'資格',certifications:'資格',employmentType:'雇用形態',contractType:'契約形態',project:'参画案件',projectName:'参画案件名',startDate:'開始日',endDate:'終了日',memo:'メモ',remark:'備考',remarks:'備考',sales:'営業担当',salesPerson:'営業担当',updatedBy:'更新者'};
        function memberJapaneseLabel(key) {
            const label=memberFieldNames[key]; if(label)return label;
            const words=String(key).replace(/([a-z])([A-Z])/g,'$1 $2').toLowerCase().split(/[\s_-]+/);
            const dict={member:'要員',employee:'社員',contact:'連絡先',date:'日',time:'時刻',start:'開始',end:'終了',price:'金額',amount:'金額',monthly:'月額',daily:'日額',hourly:'時間単価',work:'勤務',location:'場所',skill:'スキル',level:'レベル',year:'年',years:'年数',month:'月',months:'月数',name:'名称',number:'番号',code:'コード',url:'URL',link:'リンク',description:'説明',history:'履歴',details:'詳細',detail:'詳細',information:'情報',info:'情報',manager:'管理者',assigned:'担当',client:'取引先',contract:'契約',status:'状態',type:'区分',category:'分類',value:'値',flag:'フラグ',active:'有効',is:'',has:''};
            if (/[\u3040-\u30ff\u3400-\u9fff]/.test(String(key))) return String(key);
            return words.map(w=>dict[w]||'').join('') || '登録項目';
        }
        window.sesRestricted = () => window.sesCurrentAccount?.role === 'user';
        window.sesMoneyField = key => /単価|原価|交通費|売上|粗利|金額|給与|報酬|rate|cost|price|salary|revenue|profit|amount|sourceData|participants|grade|グレード/i.test(String(key));
        const memberCoreFields = new Set(['id','name','type','skills','hireDate','exp','rate','cost','available','status','waitingStartDate','nextMonthStatus','grade','assignedProjectId','contractEnd','transportCost','currentStatus']);
        function memberExtraEditor(member) {
            const root=document.getElementById('member-extra-fields'); if(!root)return;
            root.innerHTML='';
            const entries=[];
            const collect=(obj,path=[])=>Object.entries(obj).forEach(([key,value])=>{
                if(path.length===0 && memberCoreFields.has(key))return;
                if(window.sesRestricted() && window.sesMoneyField(key))return;
                if(value && typeof value==='object' && !Array.isArray(value))collect(value,[...path,key]);
                else entries.push({path:[...path,key],value});
            });
            collect(member);
            entries.forEach(({path,value})=>{
                const wrap=document.createElement('label');wrap.className='ses-member-extra-field';
                const title=document.createElement('span');title.textContent=path.map(memberJapaneseLabel).join(' / ');wrap.appendChild(title);
                const input=document.createElement('input');
                const key=path[path.length-1];
                const dateLike=/date|birthday|birthDate|\bday\b/i.test(key) && /^\d{4}-\d{2}-\d{2}$/.test(String(value||''));
                input.type=dateLike?'date':typeof value==='number'?'number':'text';
                input.value=Array.isArray(value)?value.join(', '):(value==null?'':String(value));
                input.dataset.memberPath=JSON.stringify(path);
                input.dataset.memberKind=Array.isArray(value)?'array':typeof value;
                input.className='w-full bg-slate-800 border border-slate-700 rounded-lg p-2.5 text-white';
                wrap.appendChild(input);root.appendChild(wrap);
            });
        }
        function saveMemberExtra(member) {
            document.querySelectorAll('#member-extra-fields [data-member-path]').forEach(input=>{
                const path=JSON.parse(input.dataset.memberPath);let target=member;
                for(const part of path.slice(0,-1)){if(!target[part] || typeof target[part]!=='object')target[part]={};target=target[part];}
                const kind=input.dataset.memberKind;
                target[path[path.length-1]]=kind==='array'?input.value.split(',').map(x=>x.trim()).filter(Boolean):kind==='number'?(input.value===''?null:Number(input.value)):kind==='boolean'?(input.value==='true'):input.value;
            });
        }
        function memberDetailEscape(value) { return String(value == null ? '' : value).replace(/[&<>"']/g, ch => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch])); }
        function openMemberDetailByIndex(index) {
            const m = db.members[index]; if (!m) return;
            const modal = document.getElementById('modal-member-detail');
            document.getElementById('member-detail-title').textContent = m.name || '社員詳細';
            // Detail follows the registration form's field order and grouping.
            const groups = [
                ['基本情報', ['name','type','skills','hireDate','exp','rate','cost','grade']],
                ['稼働・ステータス', ['available','status','waitingStartDate','nextMonthStatus']]
            ];
            const used = new Set(['id']);
            const field = (key,val) => window.sesRestricted() && window.sesMoneyField(key) ? '' : `<div class="ses-client-detail-field"><dt>${memberDetailEscape(memberFieldNames[key] || memberJapaneseLabel(key))}</dt><dd>${memberDetailEscape(val == null || val === '' ? '未登録' : String(val))}</dd></div>`;
            const flatten = (obj,prefix='') => Object.entries(obj||{}).flatMap(([key,value]) => {
                if(window.sesRestricted() && window.sesMoneyField(key))return [];
                const label = prefix ? prefix+' / '+(memberFieldNames[key]||memberJapaneseLabel(key)) : (memberFieldNames[key]||memberJapaneseLabel(key));
                if(value && typeof value==='object' && !Array.isArray(value)) return flatten(value,label);
                return [[label,Array.isArray(value)?value.join('、'):value]];
            });
            let html = groups.map(([title,keys]) => {
                keys.forEach(k=>used.add(k));
                return `<div class="ses-client-detail-section-title">${memberDetailEscape(title)}</div>`+keys.map(k=>field(k,m[k])).join('');
            }).join('');
            const extras=Object.fromEntries(Object.entries(m).filter(([k])=>!used.has(k)));
            const more=flatten(extras);
            if(more.length) html+=`<div class="ses-client-detail-section-title">所属・参画情報</div>`+more.map(([k,v])=>`<div class="ses-client-detail-field"><dt>${memberDetailEscape(k)}</dt><dd>${memberDetailEscape(v==null||v===''?'未登録':String(v))}</dd></div>`).join('');
            html+=`<div class="ses-client-detail-section-title">管理情報</div>`+field('id',window.getMemberDisplayId(m));
            document.getElementById('member-detail-fields').innerHTML=html;
            document.getElementById('member-detail-edit').onclick=()=>{closeModal('modal-member-detail');editMember(m.id);};
            document.getElementById('member-detail-delete').onclick=()=>{closeModal('modal-member-detail');deleteMember(m.id);};
            modal.classList.remove('hidden');
            document.getElementById('member-detail-fields').scrollTop=0;
        }
        // --- INTERVIEWS TABLE ---
        function renderInterviewsTable() {
            const tbody = document.getElementById('interviews-table-body');
            if (!tbody) return; // customer-meetings module replaces the legacy table view

            tbody.innerHTML = db.interviews.map(i => `
                <tr class="hover:bg-slate-800/40 transition">
                    <td class="p-3 font-mono text-cyan-400 font-bold">${i.date.replace('T', ' ')}</td>
                    <td class="p-3 font-bold text-slate-200">${i.memberName}</td>
                    <td class="p-3">${i.projectTitle}</td>
                    <td class="p-3">${i.clientName}</td>
                    <td class="p-3 text-slate-400">${i.location}</td>
                    <td class="p-3">
                        <span class="px-2 py-0.5 rounded text-[10px] bg-cyan-500/10 text-cyan-400 border border-cyan-500/30">
                            ${i.status}
                        </span>
                    </td>
                    <td class="p-3 text-right">
                        <button onclick="deleteInterview('${i.id}')" class="text-rose-400 hover:text-rose-300"><i class="fa-solid fa-trash"></i></button>
                    </td>
                </tr>
            `).join('');
        }

        // --- REVENUE VIEW ---
        function renderRevenueView() {
            const tbody = document.getElementById('revenue-table-body');
            const activeMembers = db.members.filter(m => m.status === '稼働中');

            let totalRev = 0;
            let totalCost = 0;

            tbody.innerHTML = activeMembers.map(m => {
                const assignedPrj = db.projects[0]; // Example fallback link
                const rateYen = Math.round((Number(m.rate)||0)*10000);
                const costYen = Math.round((Number(m.cost)||0)*10000);
                const margin = rateYen - costYen;
                const marginRate = m.rate > 0 ? ((margin / rateYen) * 100).toFixed(1) : 0;

                totalRev += rateYen;
                totalCost += costYen;

                return `
                    <tr class="hover:bg-slate-800/40 transition">
                        <td class="p-3 font-bold text-slate-200">${m.name}</td>
                        <td class="p-3 text-slate-300">${assignedPrj ? assignedPrj.title : '未紐付け'}</td>
                        <td class="p-3 text-slate-400">${assignedPrj ? assignedPrj.clientName : '-'}</td>
                        <td class="p-3 font-mono font-bold text-emerald-400">¥${rateYen.toLocaleString('ja-JP')}</td>
                        <td class="p-3 font-mono text-slate-300">¥${costYen.toLocaleString('ja-JP')}</td>
                        <td class="p-3 font-mono font-bold text-purple-400">¥${margin.toLocaleString('ja-JP')}</td>
                        <td class="p-3 font-mono">${marginRate}%</td>
                    </tr>
                `;
            }).join('');

            const totalProfit = totalRev - totalCost;
            const avgMargin = totalRev > 0 ? ((totalProfit / totalRev) * 100).toFixed(1) : 0;

            document.getElementById('rev-summary-count').innerText = `${activeMembers.length}名`;
            document.getElementById('rev-summary-total').innerText = `¥${totalRev.toLocaleString('ja-JP')}`;
            document.getElementById('rev-summary-cost').innerText = `¥${totalCost.toLocaleString('ja-JP')}`;
            document.getElementById('rev-summary-margin').innerText = `${avgMargin}%`;
        }

        // ----------------------------------------------------
        // 7. MODAL ACTIONS & CRUD HANDLERS
        // ----------------------------------------------------
        function closeModal(id) {
            document.getElementById(id).classList.add('hidden');
        }

        function updateModalDropdowns() {
            const prjClient = document.getElementById('project-client');
            if (prjClient) {
                prjClient.innerHTML = db.clients.map(c => `<option value="${c.id}">${c.name}</option>`).join('');
            }

            const intMember = document.getElementById('interview-member');
            if (intMember) {
                intMember.innerHTML = db.members.map(m => `<option value="${m.id}">${m.name} (${m.skills[0] || ''})</option>`).join('');
            }

            const intProject = document.getElementById('interview-project');
            if (intProject) {
                intProject.innerHTML = db.projects.map(p => `<option value="${p.id}">${p.title}</option>`).join('');
            }
        }

        // --- CLIENT CRUD ---
        // Edit every stored client field without dropping unknown legacy fields.
        const clientStandardFields = new Set(['id','name','type','contact','email','status']);
        const clientFieldLabels = {activeProjects:'公開中案件数',meetingDate:'打合せ日',meetingRoute:'打合せまでの流れ',department:'部署名',position:'役職',address:'住所',url:'企業URL',notes:'備考',skillMemo:'スキルメモ',enteredBy:'記入者名',sourceData:'登録元の詳細情報'};
        let clientExtraPaths = [];
        function renderClientExtraFields(client) {
            const area = document.getElementById('client-extra-fields');
            if (!area) return;
            clientExtraPaths = [];
            const fields = [];
            const walk = (value, path, label) => {
                if (value && typeof value === 'object' && !Array.isArray(value)) {
                    Object.entries(value).forEach(([key, child]) => walk(child, [...path,key], clientFieldLabels[key] || memberJapaneseLabel(key)));
                    return;
                }
                const index = clientExtraPaths.push({path,original:value}) - 1;
                const display = Array.isArray(value) ? value.map(v => typeof v === 'object' ? Object.values(v).join('・') : v).join('、') : String(value ?? '');
                const isDate = typeof value === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(value) && /(date|日|開始|終了)/i.test(label + path.join(''));
                const input = typeof value === 'number' ? `<input type="number" step="any" id="client-extra-${index}" data-client-extra="${index}" value="${clientDisplayText(display)}">` : isDate ? `<input type="date" id="client-extra-${index}" data-client-extra="${index}" value="${clientDisplayText(display)}">` : `<textarea id="client-extra-${index}" rows="2" data-client-extra="${index}">${clientDisplayText(display)}</textarea>`;
                fields.push(`<div><label for="client-extra-${index}">${clientDisplayText(label)}</label>${input}</div>`);
            };
            Object.entries(client || {}).filter(([key]) => !clientStandardFields.has(key)).forEach(([key,value]) => walk(value,[key],clientFieldLabels[key] || memberJapaneseLabel(key)));
            area.innerHTML = fields.join('');
        }
        function saveClientExtraFields(client) {
            clientExtraPaths.forEach(({path,original}, index) => {
                const el = document.getElementById(`client-extra-${index}`);
                if (!el) return;
                const value = el.value;
                let parsed = value;
                if (typeof original === 'number' && value.trim() !== '' && Number.isFinite(Number(value))) parsed = Number(value);
                else if (typeof original === 'boolean') parsed = value === 'true' ? true : value === 'false' ? false : value;
                else if (Array.isArray(original)) parsed = value.trim() ? value.split('、').map(v => v.trim()) : [];
                let target = client;
                for (const key of path.slice(0,-1)) target = target[key];
                target[path[path.length-1]] = parsed;
            });
        }
        function openClientModal() {
            document.getElementById('form-client').reset();
            document.getElementById('client-type').value = '取引先(SES)';
            // Use the existing client schema so new records expose the same fields as detail/edit.
            const schemaClient = (db.clients || []).find(c => c && c.sourceData && typeof c.sourceData === 'object') || (db.clients || [])[0];
            const blankClient = {};
            if (schemaClient) {
                Object.entries(schemaClient).forEach(([key, value]) => {
                    if (clientStandardFields.has(key)) return;
                    const blank = v => Array.isArray(v) ? [] : (v && typeof v === 'object') ? Object.fromEntries(Object.entries(v).map(([k, child]) => [k, blank(child)])) : typeof v === 'number' ? 0 : typeof v === 'boolean' ? false : '';
                    blankClient[key] = blank(value);
                });
            }
            renderClientExtraFields(blankClient);
            document.getElementById('client-id').value = '';
            document.getElementById('modal-client-title').innerText = '新規取引先追加';
            document.getElementById('modal-client').classList.remove('hidden');
        }

        function editClient(id) {
            const client = db.clients.find(c => c.id === id);
            if (!client) return;
            document.getElementById('client-id').value = client.id;
            document.getElementById('client-name').value = client.name;
            document.getElementById('client-type').value = client.type;
            document.getElementById('client-contact').value = client.contact;
            document.getElementById('client-email').value = client.email;
            document.getElementById('client-status').value = client.status;
            renderClientExtraFields(client);
            document.getElementById('modal-client-title').innerText = '取引先編集';
            document.getElementById('modal-client').classList.remove('hidden');
        }

        function saveClient(e) {
            e.preventDefault();
            const id = document.getElementById('client-id').value;
            const name = document.getElementById('client-name').value;
            const type = document.getElementById('client-type').value;
            const contact = document.getElementById('client-contact').value;
            const email = document.getElementById('client-email').value;
            const status = document.getElementById('client-status').value;

            if (id) {
                const index = db.clients.findIndex(c => c.id === id);
                if (index !== -1) {
                    const updated = { ...db.clients[index], name, type, contact, email, status };
                    saveClientExtraFields(updated);
                    db.clients[index] = updated;
                }
            } else {
                db.clientIdSequence = Math.max(Number(db.clientIdSequence)||0, ...db.clients.map(c=>/^CLI-\d+$/.test(c.id)?Number(c.id.slice(4)):0))+1;
                const newId = `CLI-${String(db.clientIdSequence).padStart(3, '0')}`;
                const created = { id: newId, name, type, contact, email, activeProjects: 0, status };
                clientExtraPaths.forEach(({path}) => {
                    let target = created;
                    for (const key of path.slice(0, -1)) {
                        if (!target[key] || typeof target[key] !== 'object') target[key] = {};
                        target = target[key];
                    }
                    if (!(path[path.length - 1] in target)) target[path[path.length - 1]] = '';
                });
                saveClientExtraFields(created);
                db.clients.push(created);
            }

            saveStoredData();
            closeModal('modal-client');
            window.sesActionNotice?.(id ? 'update' : 'create');
            if (id) { const saved = db.clients.find(c => c.id === id); if (saved) openClientDetailByIndex(db.clients.findIndex(c => c.id === saved.id)); }
        }

        function deleteClient(id) {
            if (confirm("この取引先を削除しますか？")) {
                db.clients = db.clients.filter(c => c.id !== id);
                saveStoredData();
                window.sesActionNotice?.('delete');
            }
        }


        const projectInfoEscape = value => String(value == null ? '' : value).replace(/[&<>"']/g, ch => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
        const projectInfoLabels = {id:'案件ID',title:'案件名称',clientId:'取引先ID',clientName:'クライアント',skills:'必須スキル',price:'想定単価（万円）',priceYen:'想定単価（円）',location:'勤務形態',status:'ステータス',projectType:'案件区分',assignedMemberIds:'参画メンバーID',participants:'参画メンバー',startDate:'開始日',endDate:'終了日',description:'案件内容',notes:'備考',createdAt:'登録日時',updatedAt:'更新日時',sourceData:'登録元情報',contractEnd:'契約終了日',proposedMember:'提案要員',settlementHours:'精算時間',commercialFlow:'商流',requiredSkills:'必須スキル詳細',desirableSkills:'尚可スキル',interviewCount:'面談回数',nextAction:'次回アクション・備考',clientContact:'取引先担当者'};
        function projectInfoField(label, value) {
            const display = value == null || value === '' ? '未登録' : String(value);
            return `<div class="ses-client-detail-field"><dt>${projectInfoEscape(label)}</dt><dd>${projectInfoEscape(display)}</dd></div>`;
        }
        // Keep nested source fields flat: a card must never contain another field grid.
        function projectInfoEntries(data, prefix = '') {
            if (!data || typeof data !== 'object') return '';
            return Object.entries(data).map(([key, value]) => {
                const name = projectInfoLabels[key] || memberJapaneseLabel(key);
                const label = prefix ? `${prefix} / ${name}` : name;
                if (Array.isArray(value)) {
                    if (!value.length) return projectInfoField(label, '未登録');
                    if (value.every(v => v == null || typeof v !== 'object'))
                        return projectInfoField(label, value.map(v => v == null ? '' : String(v)).join('、'));
                    return value.map((item, i) => item && typeof item === 'object'
                        ? projectInfoEntries(item, `${label} ${i + 1}`)
                        : projectInfoField(`${label} ${i + 1}`, item)).join('');
                }
                if (value && typeof value === 'object') return projectInfoEntries(value, label);
                return projectInfoField(label, value);
            }).join('');
        }
        function openProjectInfoByIndex(index) {
            const p = db.projects[index]; if (!p) return;
            document.getElementById('project-info-title').textContent = p.title || '案件詳細';
            const field = (label, value) => window.sesRestricted() && window.sesMoneyField(label) ? '' : `<div class="project-read-field"><label>${projectInfoEscape(label)}</label><div class="project-read-value">${projectInfoEscape(value == null || value === '' ? '未登録' : value)}</div></div>`;
            const section = label => `<div class="ses-client-section-title">${label}</div>`;
            const group = content => `<div class="project-read-group">${content}</div>`;
            const extra = Object.entries(p).filter(([key]) => !projectCoreKeys.has(key) && (!window.sesRestricted() || (!window.sesMoneyField(key) && typeof p[key] !== 'object'))).map(([key,value]) => field(projectInfoLabels[key] || memberJapaneseLabel(key), Array.isArray(value) ? value.map(v=>typeof v==='object' && v!==null ? Object.entries(v).map(([k,x])=>`${projectInfoLabels[k]||memberJapaneseLabel(k)}：${x}`).join(' / ') : v).join('、') : value !== null && typeof value === 'object' ? Object.entries(value).map(([k,v])=>`${projectInfoLabels[k]||memberJapaneseLabel(k)}：${v}`).join('\n') : value)).join('');
            const client = db.clients.find(c => c.id === p.clientId);
            document.getElementById('project-info-fields').innerHTML = section('基本情報') + field('案件名称',p.title) + group(field('発注元クライアント',client?.name || p.clientName) + field('案件想定単価（円/月）',projectPriceYen(p).toLocaleString('ja-JP'))) + field('必須スキル・技術 (カンマ区切り)',(p.skills || []).join(', ')) + group(field('勤務形態',p.location)+field('案件区分',inferredProjectType(p))+field('ステータス',p.status)) + section('案件・契約情報') + group(extra) + `<div class="project-read-group project-date-row">${field('開始日',p.startDate)}${field('契約終了日',p.contractEnd)}</div>`;
            document.getElementById('project-info-fields').scrollTop = 0;
            document.getElementById('project-info-edit').onclick = () => {closeModal('modal-project-info');editProject(p.id);};
            document.getElementById('project-info-delete').onclick = () => {closeModal('modal-project-info');deleteProject(p.id);};
            document.getElementById('modal-project-info').classList.remove('hidden');
        }
        window.openProjectInfoByIndex = openProjectInfoByIndex;
        const projectCoreKeys = new Set(['id','title','clientId','clientName','price','priceYen','skills','location','status','projectType','startDate','contractEnd']);
        function renderProjectExtraFields(p) {
            const target = document.getElementById('project-extra-fields'); if (!target) return;
            target.innerHTML = p ? Object.entries(p).filter(([k])=>!projectCoreKeys.has(k) && (!window.sesRestricted() || (!window.sesMoneyField(k) && typeof p[k] !== 'object'))).map(([key,value]) => {
                const label=projectInfoLabels[key]||memberJapaneseLabel(key);
                const serialized = value !== null && typeof value === 'object' ? JSON.stringify(value,null,2) : String(value ?? '');
                const fieldType = Array.isArray(value)?'array':value===null?'null':typeof value;
                const dateField = typeof value === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(value) && /(date|日|開始|終了)/i.test(key+label);
                const attrs = `class="w-full bg-slate-800 border border-slate-700 rounded-lg p-2.5 text-white" data-project-extra="${projectInfoEscape(key)}" data-project-type="${fieldType}"`;
                const control = fieldType === 'number' ? `<input type="number" step="any" ${attrs} value="${projectInfoEscape(serialized)}">` : dateField ? `<input type="date" ${attrs} value="${projectInfoEscape(serialized)}">` : `<textarea ${attrs} rows="${typeof value === 'object' && value !== null ? 3 : 2}">${projectInfoEscape(serialized)}</textarea>`;
                return `<div><label class="block text-slate-400 mb-1">${projectInfoEscape(label)}</label>${control}</div>`;
            }).join('') : '';
        }
        function readProjectExtraFields() {
            const result={};
            document.querySelectorAll('#project-extra-fields [data-project-extra]').forEach(el=>{
                const type=el.dataset.projectType; const raw=el.value;
                if (type==='array'||type==='object') {try{const parsed=JSON.parse(raw);if ((type==='array'&& !Array.isArray(parsed))||(type==='object'&&(parsed===null||Array.isArray(parsed)||typeof parsed!=='object')))throw Error();result[el.dataset.projectExtra]=parsed;}catch(e){throw new Error(`${el.previousElementSibling?.textContent||el.dataset.projectExtra}の形式を確認してください`);}}
                else if(type==='number') result[el.dataset.projectExtra]=Number(raw)||0;
                else if(type==='boolean') result[el.dataset.projectExtra]=raw==='true';
                else result[el.dataset.projectExtra]=type==='null'&&raw===''?null:raw;
            });
            return result;
        }

        // --- PROJECT CRUD ---
        function openProjectModal() {
            document.getElementById('form-project').reset();
            renderProjectExtraFields(null);
            document.getElementById('project-id').value = '';
            document.getElementById('modal-project-title').innerText = '新規案件登録';
            const projectTypeInput = document.getElementById('project-type');
            if (projectTypeInput) projectTypeInput.value = projectViewMode;
            document.getElementById('modal-project').classList.remove('hidden');
        }

        function editProject(id) {
            const prj = db.projects.find(p => p.id === id);
            if (!prj) return;
            renderProjectExtraFields(prj);
            document.getElementById('project-id').value = prj.id;
            document.getElementById('project-title').value = prj.title;
            document.getElementById('project-client').value = prj.clientId;
            document.getElementById('project-price').value = projectPriceYen(prj);
            document.getElementById('project-skills').value = prj.skills.join(', ');
            document.getElementById('project-location').value = prj.location;
            document.getElementById('project-status').value = prj.status;
            const projectTypeInput = document.getElementById('project-type');
            if (projectTypeInput) projectTypeInput.value = inferredProjectType(prj);
            document.getElementById('modal-project-title').innerText = '案件情報編集';
            document.getElementById('modal-project').classList.remove('hidden');
        }

        function saveProject(e) {
            e.preventDefault();
            const id = document.getElementById('project-id').value;
            const title = document.getElementById('project-title').value;
            const clientId = document.getElementById('project-client').value;
            const clientObj = db.clients.find(c => c.id === clientId);
            const clientName = clientObj ? clientObj.name : '不明クライアント';
            const priceYen = window.sesRestricted() ? projectPriceYen(db.projects.find(p=>p.id===id)||{}) : Math.max(0, Math.round(Number(document.getElementById('project-price').value) || 0));
            const price = priceYen / 10000;
            const skills = document.getElementById('project-skills').value.split(',').map(s => s.trim()).filter(s => s);
            const location = document.getElementById('project-location').value;
            const status = document.getElementById('project-status').value;
            const projectType = document.getElementById('project-type')?.value || projectViewMode || '共有案件';
            let extra; try { extra = {...readProjectExtraFields(), startDate: document.getElementById('project-start-date').value, contractEnd: document.getElementById('project-contract-end').value}; } catch (error) { alert(error.message); return; }

            if (id) {
                const index = db.projects.findIndex(p => p.id === id);
                if (index !== -1) db.projects[index] = { ...db.projects[index], title, clientId, clientName, price, priceYen, skills, location, status, projectType, ...extra };
            } else {
                const maxId = db.projects.reduce((max, p) => { const match = /^PRJ-(\d+)$/.exec(p.id); return match ? Math.max(max, Number(match[1])) : max; }, 0);
                db.projectIdSequence = Math.max(Number(db.projectIdSequence) || 0, maxId) + 1;
                const newId = `PRJ-${String(db.projectIdSequence).padStart(3, '0')}`;
                db.projects.push({ id: newId, title, clientId, clientName, price, priceYen, skills, location, status, projectType, assignedMemberIds: [], participants: [], ...extra });
            }

            saveStoredData();
            closeModal('modal-project');
            if (id) { const index = db.projects.findIndex(p => p.id === id); if (index >= 0) openProjectInfoByIndex(index); }
        }

        function getProjectParticipants(project) {
            const explicit = (project.participants || []).filter(x => x && x.memberId);
            const merged = [...explicit];
            (project.assignedMemberIds || []).forEach(memberId => { if (!merged.some(x => x.memberId === memberId)) merged.push({ memberId, rateYen: 0 }); });
            (db.members || []).forEach(m => {
                if ((m.assignedProjectId === project.id || m.currentProject === project.title) && !merged.some(x => x.memberId === m.id)) {
                    merged.push({ memberId: m.id, rateYen: Math.round((Number(m.rate) || 0) * 10000) });
                }
            });
            return merged;
        }
        function openProjectDetail(id) {
            const p = db.projects.find(x => x.id === id); if (!p) return;
            projectDetailId = id;
            document.getElementById('project-detail-title').textContent = p.title;
            document.getElementById('project-detail-subtitle').textContent = `${p.clientName || '取引先未登録'}${window.sesRestricted()?'':` ／ 案件想定単価：${formatYenAsMan(projectPriceYen(p))}万円/月`} ／ ステータス：${p.status || '未設定'}`;
            const select = document.getElementById('participant-member');
            const participants = getProjectParticipants(p);
            select.innerHTML = '<option value="">メンバーを選択</option>' + db.members.map(m => `<option value="${m.id}" ${participants.some(x => x.memberId === m.id) ? 'disabled' : ''}>${m.name}（${m.id}）${participants.some(x => x.memberId === m.id) ? '・登録済み' : ''}</option>`).join('');
            document.getElementById('participant-rate-yen').value = '';
            renderProjectParticipants();
            document.getElementById('modal-project-detail').classList.remove('hidden');
        }
        function renderProjectParticipants() {
            const p = db.projects.find(x => x.id === projectDetailId); if (!p) return;
            const participants = getProjectParticipants(p);
            if(window.sesRestricted()){document.getElementById("project-participants-body").innerHTML=participants.map(x=>`<tr><td class="p-3">${projectInfoEscape(db.members.find(m=>m.id===x.memberId)?.name||x.memberId)}</td></tr>`).join("");return;}
            document.getElementById('project-participants-body').innerHTML = participants.length ? participants.map(x => {
                const m = db.members.find(mm => mm.id === x.memberId);
                return `<tr><td class="p-3 font-semibold text-slate-200">${m ? m.name : '削除済みメンバー'} <span class="text-slate-500">${x.memberId}</span></td><td class="p-3 font-mono text-amber-300">${formatYenAsMan(x.rateYen)}万円/月</td><td class="p-3 font-mono">¥${Math.round(Number(x.rateYen)||0).toLocaleString('ja-JP')}</td><td class="p-3 text-right whitespace-nowrap"><button onclick="editProjectParticipant('${x.memberId}')" class="text-cyan-400 mr-3">単価変更</button><button onclick="removeProjectParticipant('${x.memberId}')" class="text-rose-400">解除</button></td></tr>`;
            }).join('') : '<tr><td colspan="4" class="p-5 text-center text-slate-500">参画メンバーはまだ登録されていません。</td></tr>';
            const select = document.getElementById('participant-member');
            if (select) Array.from(select.options).forEach(o => { if (o.value) { const exists = participants.some(x => x.memberId === o.value); o.disabled = exists; o.textContent = (db.members.find(m => m.id === o.value)?.name || o.value) + (exists ? '・登録済み' : ''); } });
        }
        function addProjectParticipant() {
            if(window.sesRestricted?.()) return;
            const p = db.projects.find(x => x.id === projectDetailId); if (!p) return;
            const memberId = document.getElementById('participant-member').value;
            const rateField = document.getElementById('participant-rate-yen');
            if (!memberId) { alert('参画メンバーを選択してください。'); return; }
            if (rateField.value === '' || !Number.isFinite(Number(rateField.value)) || Number(rateField.value) < 0) { alert('参画単価を円単位で入力してください。'); return; }
            p.participants = Array.isArray(p.participants) ? p.participants : [];
            if (getProjectParticipants(p).some(x => x.memberId === memberId)) { alert('このメンバーは登録済みです。'); return; }
            p.participants.push({ memberId, rateYen: Math.round(Number(rateField.value)) });
            p.assignedMemberIds = [...new Set([...(p.assignedMemberIds || []), memberId])];
            p.projectType = '参画案件';
            if (p.status === '提案公募中' || p.status === '募集準備中' || p.status === '募集終了') p.status = '参画中';
            saveStoredData(); openProjectDetail(projectDetailId);
        }
        function editProjectParticipant(memberId) {
            if(window.sesRestricted?.()) return;
            const p = db.projects.find(x => x.id === projectDetailId); if (!p) return;
            const item = getProjectParticipants(p).find(x => x.memberId === memberId); if (!item) return;
            const input = prompt('参画単価を円単位で入力してください（1円単位）', String(Math.round(Number(item.rateYen)||0)));
            if (input === null) return;
            if (input.trim() === '' || !Number.isFinite(Number(input)) || Number(input) < 0) { alert('0以上の金額を入力してください。'); return; }
            p.participants = Array.isArray(p.participants) ? p.participants : [];
            let row = p.participants.find(x => x.memberId === memberId);
            if (!row) { row = { memberId, rateYen: 0 }; p.participants.push(row); }
            row.rateYen = Math.round(Number(input));
            saveStoredData(); openProjectDetail(projectDetailId);
        }
        function removeProjectParticipant(memberId) {
            if(window.sesRestricted?.()) return;
            const p = db.projects.find(x => x.id === projectDetailId); if (!p) return;
            const m = db.members.find(x => x.id === memberId);
            if (!confirm(`${m ? m.name : memberId} をこの案件の参画メンバーから解除しますか？`)) return;
            p.participants = (p.participants || []).filter(x => x.memberId !== memberId);
            p.assignedMemberIds = (p.assignedMemberIds || []).filter(x => x !== memberId);
            saveStoredData(); openProjectDetail(projectDetailId);
        }

        function deleteProject(id) {
            if (confirm("この案件を削除しますか？")) {
                db.projects = db.projects.filter(p => p.id !== id);
                saveStoredData();
            }
        }

        // --- MEMBER CRUD ---
        function openMemberModal() {
            document.getElementById('form-member').reset();
            document.getElementById('member-id').value = '';
            const hireInput = document.getElementById('member-hire-date'); if (hireInput) hireInput.value = '';
            document.getElementById('member-exp').value = '';
            document.getElementById('modal-member-title').innerText = '新規社員登録';
            const defaults={}; for(const item of db.members||[]) for(const [key,value] of Object.entries(item)) if(!memberCoreFields.has(key)&&!(key in defaults)) defaults[key]=Array.isArray(value)?[]:value&&typeof value==='object'?{}:typeof value==='number'?0:'';
            memberExtraEditor(defaults);
            document.getElementById('member-display-id').textContent='登録時に採番';
            document.getElementById('member-submit').textContent='登録';
            document.querySelector('#modal-member .ses-member-body').scrollTop=0;
            window.fillMemberGradeSelect?.('');
            document.getElementById('member-next-month-status').value='稼働中';
            document.getElementById('modal-member').classList.remove('hidden');
        }

        function editMember(id) {
            const m = db.members.find(item => item.id === id);
            if (!m) return;
            document.getElementById('member-id').value = m.id;
            document.getElementById('member-name').value = m.name;
            document.getElementById('member-type').value = m.type;
            document.getElementById('member-skills').value = m.skills.join(', ');
            document.getElementById('member-hire-date').value = m.hireDate || '';
            document.getElementById('member-exp').value = window.calculateTenure ? window.calculateTenure(m.hireDate) : (m.exp || '');
            document.getElementById('member-rate').value = Math.round((Number(m.rate)||0)*10000);
            document.getElementById('member-cost').value = Math.round((Number(m.cost)||0)*10000);
            document.getElementById('member-available').value = m.available;
            document.getElementById('member-status').value = m.status;
            document.getElementById('member-waiting-start').value = m.waitingStartDate || '';
            document.getElementById('modal-member-title').innerText = '社員情報編集';
            document.getElementById('member-next-month-status').value=m.nextMonthStatus || m.status || '稼働中';
            memberExtraEditor(m);
            document.getElementById('member-display-id').textContent=window.getMemberDisplayId(m);
            document.getElementById('member-submit').textContent='保存';
            document.querySelector('#modal-member .ses-member-body').scrollTop=0;
            window.fillMemberGradeSelect?.(m.grade||'');
            document.getElementById('modal-member').classList.remove('hidden');
        }

        function saveMember(e) {
            e.preventDefault();
            const id = document.getElementById('member-id').value;
            const name = document.getElementById('member-name').value;
            const type = document.getElementById('member-type').value;
            const skills = document.getElementById('member-skills').value.split(',').map(s => s.trim()).filter(s => s);
            const hireDate = document.getElementById('member-hire-date').value;
            const exp = window.calculateTenure ? window.calculateTenure(hireDate) : ''; 
            const prior = db.members.find(m=>m.id===id);
            const rate = window.sesRestricted() ? Number(prior?.rate||0) : Math.round(Number(document.getElementById('member-rate').value)||0)/10000;
            const cost = window.sesRestricted() ? Number(prior?.cost||0) : (Math.round(Number(document.getElementById('member-cost').value)||0)/10000);
            const available = document.getElementById('member-available').value;
            const status = document.getElementById('member-status').value;
            const waitingStartDate = document.getElementById('member-waiting-start').value;
            const nextMonthStatus = document.getElementById('member-next-month-status').value;
            const grade = window.sesRestricted() ? (prior?.grade||'') : document.getElementById('member-grade')?.value || '';
            const assignedProjectId = document.getElementById('member-project').value;
            const contractEnd = document.getElementById('member-contract-end').value;
            const transportCost = window.sesRestricted() ? Number(prior?.transportCost||0) : Math.round(Math.max(0, Number(document.getElementById('member-transport-cost').value)||0))/10000;
            const currentStatus = status;

            if (id) {
                const index = db.members.findIndex(m => m.id === id);
                if (index !== -1) { db.members[index] = { ...db.members[index], name, type, skills, hireDate, exp, rate, cost, available, status, waitingStartDate, nextMonthStatus, grade, currentStatus, assignedProjectId, contractEnd, transportCost }; saveMemberExtra(db.members[index]); if(prior.grade!==grade){window.applyGradeToPlan?.(db.members[index]); db.members[index].cost=cost;} }
            } else {
                db.memberIdSequence = Math.max(Number(db.memberIdSequence)||0, ...db.members.map(c=>/^MEM-\d+$/.test(c.id)?Number(c.id.slice(4)):0))+1;
                const newId = `MEM-${String(db.memberIdSequence).padStart(3, '0')}`;
                const member={ id: newId, name, type, skills, hireDate, exp, rate, cost, available, status, waitingStartDate, nextMonthStatus, grade, currentStatus, assignedProjectId, contractEnd, transportCost };
                saveMemberExtra(member); db.members.push(member);
            }

            saveStoredData();
            closeModal('modal-member');
            window.sesActionNotice?.(id ? 'update' : 'create');
            if (id) { const index=db.members.findIndex(m=>m.id===id); if(index>=0)openMemberDetailByIndex(index); }
        }

        function deleteMember(id) {
            if (confirm("この要員情報を削除しますか？")) {
                db.members = db.members.filter(m => m.id !== id);
                saveStoredData();
                window.sesActionNotice?.('delete');
            }
        }

        // --- INTERVIEW CRUD ---
        function openInterviewModal() {
            document.getElementById('form-interview').reset();
            document.getElementById('modal-interview').classList.remove('hidden');
        }

        function saveInterview(e) {
            e.preventDefault();
            const memberId = document.getElementById('interview-member').value;
            const projectId = document.getElementById('interview-project').value;
            const date = document.getElementById('interview-date').value;
            const location = document.getElementById('interview-location').value;
            const status = document.getElementById('interview-status').value;

            const member = db.members.find(m => m.id === memberId);
            const project = db.projects.find(p => p.id === projectId);

            db.interviewIdSequence = Math.max(500,Number(db.interviewIdSequence)||0,...db.interviews.map(c=>/^INT-\d+$/.test(c.id)?Number(c.id.slice(4)):0))+1;
            const newId = `INT-${String(db.interviewIdSequence).padStart(3,'0')}`;
            db.interviews.push({
                id: newId,
                memberId,
                memberName: member ? member.name : '要員',
                projectId,
                projectTitle: project ? project.title : '案件',
                clientName: project ? project.clientName : 'クライアント',
                date,
                location,
                status
            });

            saveStoredData();
            closeModal('modal-interview');
            window.sesActionNotice?.('create');
        }

        function deleteInterview(id) {
            if (confirm("この面談履歴を削除しますか？")) {
                db.interviews = db.interviews.filter(i => i.id !== id);
                saveStoredData();
                window.sesActionNotice?.('delete');
            }
        }

        // ----------------------------------------------------
        // 8. CHART.JS INITIALIZATION & UPDATES
        // ----------------------------------------------------
        function initCharts() {
            const isNeon = document.body.classList.contains('theme-neon');
            const textColor = isNeon ? '#94A3B8' : '#64748B';
            const gridColor = isNeon ? 'rgba(255,255,255,0.05)' : '#E2E8F0';

            // Revenue Trend Chart
            const ctxRev = document.getElementById('chart-revenue-trend');
            if (ctxRev) {
                if (revenueChart) revenueChart.destroy();
                revenueChart = new Chart(ctxRev, {
                    type: 'bar',
                    data: {
                        labels: ['5月', '6月', '7月', '8月', '9月', '10月 (見込)'],
                        datasets: [
                            {
                                label: '売上高 (万円)',
                                data: [380, 420, 450, 480, 510, 540],
                                backgroundColor: isNeon ? 'rgba(6, 182, 212, 0.7)' : '#2563EB',
                                borderRadius: 6
                            },
                            {
                                label: '粗利益 (万円)',
                                data: [110, 125, 135, 140, 150, 160],
                                backgroundColor: isNeon ? 'rgba(139, 92, 246, 0.7)' : '#9333EA',
                                borderRadius: 6
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            legend: { labels: { color: textColor, font: { size: 11 } } }
                        },
                        scales: {
                            x: { ticks: { color: textColor }, grid: { color: gridColor } },
                            y: { ticks: { color: textColor }, grid: { color: gridColor } }
                        }
                    }
                });
            }

            // Pipeline Funnel Chart
            const ctxFunnel = document.getElementById('chart-pipeline-funnel');
            if (ctxFunnel) {
                if (funnelChart) funnelChart.destroy();
                funnelChart = new Chart(ctxFunnel, {
                    type: 'doughnut',
                    data: {
                        labels: ['提案公募', '社内選考', '面談調整', '成約・参画'],
                        datasets: [{
                            data: [12, 5, 3, 8],
                            backgroundColor: [
                                '#06B6D4',
                                '#3B82F6',
                                '#8B5CF6',
                                '#10B981'
                            ],
                            borderWidth: 0
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            legend: { position: 'bottom', labels: { color: textColor, font: { size: 10 } } }
                        },
                        cutout: '65%'
                    }
                });
            }
        }
    